@CrossOrigin
@RestController
@RequestMapping("/IssueQuery")
public class IssueQueryRestController extends BaseSpringRestController {
	
	public IssueQueryRestController( IssueService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Issue using a UUID
     * @param		UUID issueId
     * @return		Issue
     */    
    @GetMapping("/load")
    public Issue load( @RequestParam(required=true) UUID issueId ) {
    	Issue entity = null;

    	try {  
    		entity = service.getIssue( new IssueFetchOneSummary( issueId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Issue using Id " + issueId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Issue business objects
     * @return		Set<Issue>
     */
    @GetMapping("/")
    public List<Issue> loadAll() {                
    	List<Issue> issueList = null;
        
    	try {
            // load the Issue
            issueList = service.getAllIssue();
            
            if ( issueList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Issues" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Issues ", exc );
        	return null;
        }

        return issueList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Issue issue = null;
    protected IssueService service = null;
    private static final Logger LOGGER = Logger.getLogger(IssueQueryRestController.class.getName());
    
}
